using IndieRun;
using System.IO;
using System.Reflection;
using System.Diagnostics;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using System.Windows.Threading;
using System.Xml.Linq;

static class Program
{
    static void Check(bool value,string message){if(!value)throw new Exception(message);}
    static T Copy<T>(T value)=>JsonSerializer.Deserialize<T>(JsonSerializer.Serialize(value))!;
    static void Hook(BackupEngine e,Action<string> hook)=>typeof(BackupEngine).GetProperty("Checkpoint",BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(e,hook);
    static object? Call(object o,string name,params object?[] args)=>o.GetType().GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.DeclaredOnly)!.Invoke(o,args);
    static void Set(object o,string name,object? value)=>o.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Public|BindingFlags.Instance)!.SetValue(o,value);
    static T Get<T>(object o,string name)=>(T)o.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Public|BindingFlags.Instance)!.GetValue(o)!;
    static void Wait(Task task){var frame=new DispatcherFrame();task.ContinueWith(_=>Application.Current.Dispatcher.BeginInvoke(new Action(()=>frame.Continue=false)));Dispatcher.PushFrame(frame);task.GetAwaiter().GetResult();}
    static void Refuse(Action action){try{action();}catch(Exception ex) when(ex is IOException or InvalidDataException or UnauthorizedAccessException or ArgumentException){return;}throw new Exception("Expected refusal");}
    static Package Fixture(string folder)
    {
        var path=Path.Combine(folder,"input","Bundle");Directory.CreateDirectory(path);File.WriteAllText(Path.Combine(path,"Game.exe"),"generated fixture, do not run");
        foreach(var d in new[]{"Data","Comics","OtherGame","Scratch"}){Directory.CreateDirectory(Path.Combine(path,d));File.WriteAllText(Path.Combine(path,d,d=="OtherGame"?"Other.exe":"data.txt"),"fixture "+d);}
        Directory.CreateDirectory(Path.Combine(path,"Data","Empty"));return new(){IsReal=true,Registered=false,Id=Guid.NewGuid().ToString("N"),Source=path,DetectedRoot=path,SearchRoot=Path.Combine(folder,"input"),Folder="Bundle",Name="Bundle",Alias="작은 정원"};
    }
    static MainWindow Window(string folder,List<Package> packages,ScanSnapshot scan)
    {
        var w=new MainWindow();Set(w,"packages",packages);Set(w,"selected",packages[0]);Set(w,"snapshot",scan);Set(w,"source",Path.Combine(folder,"input"));Set(w,"searchLocations",new List<SearchLocation>{new(){Path=Path.Combine(folder,"input")}});Set(w,"destination",Path.Combine(folder,"library"));Set(w,"playerRoot",Path.Combine(folder,"library"));Set(w,"backupStorageRoot",Path.Combine(folder,"backups"));Set(w,"checkpoints",packages.Select(p=>WorkspaceReconciler.Capture(p,scan)).ToList());return w;
    }
    static IEnumerable<DependencyObject> Visual(DependencyObject root){yield return root;for(int i=0;i<System.Windows.Media.VisualTreeHelper.GetChildrenCount(root);i++)foreach(var node in Visual(System.Windows.Media.VisualTreeHelper.GetChild(root,i)))yield return node;}
    static void Close(MainWindow w){Set(w,"closingWithoutSave",true);w.Close();}
    [STAThread]static int Main(string[] args)
    {
        if(args[0]=="--seed-demo")
        {
            DemoSetup.Initialize(args[1]);var data=Path.Combine(args[1],"data");var plan=new WorkspaceStore(Path.Combine(data,"workspace.json")).Load().Document!;var tags=new TagCatalogStore(Path.Combine(data,"tags.json")).Load();var play=new PlayerStore(plan.Destination).Load();var games=plan.Packages.Where(p=>p.Registered==true&&!p.IsRelatedContent).Take(2).ToList();var batch=new RenameBatch(data);batch.Begin(plan,tags,play,games.Select(p=>new RenameTarget{PackageId=p.Id,Original=p.Source,Current=p.Source,Name=p.Folder+"_Checked"}).ToList());batch.ContinueAsync().GetAwaiter().GetResult();Console.WriteLine("SEEDED");return 0;
        }
        if(args[0]=="--batch-child"){var b=new RenameBatch(args[1]);b.Checkpoint=p=>{if(p==args[2]){Console.WriteLine("READY");Console.Out.Flush();Thread.Sleep(Timeout.Infinite);}};b.ContinueAsync().GetAwaiter().GetResult();return 0;}
        if(args[0]=="--rename-child")
        {
            var service=new FolderRename(args[1]);service.Checkpoint=point=>{if(point==args[3]){Console.WriteLine("READY");Console.Out.Flush();Thread.Sleep(Timeout.Infinite);}};service.Commit(JsonSerializer.Deserialize<RenameRecord>(File.ReadAllText(args[2]))!);return 0;
        }
        var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var styles=XDocument.Load(Path.Combine(AppContext.BaseDirectory,"styles-source.xaml")).Root!.Elements().Single().Elements().Single();app.Resources=(ResourceDictionary)XamlReader.Parse(styles.ToString(),new ParserContext{BaseUri=new Uri(AppContext.BaseDirectory)});SynchronizationContext.SetSynchronizationContext(null);
        var root=Path.Combine(Path.GetFullPath(args[0]),"run-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var results=new List<object>();int failed=0;
        void Test(string name,Action<string> action){var path=Path.Combine(root,name);Directory.CreateDirectory(path);try{action(path);results.Add(new{name,status="PASS"});Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;results.Add(new{name,status="FAIL",error=ex.ToString()});Console.WriteLine("FAIL "+name+": "+ex.Message);}}
        (WorkspaceDocument Plan,TagCatalog Tags,PlayerDocument Play,Package Main,Package Second,Package Asset) Data(string folder)
        {
            var p=Fixture(folder);p.Registered=true;p.Contents.Add(new(){Path="Comics",Role="related",Alias="디지털 만화"});var other=Fixture(Path.Combine(folder,"second"));other.Registered=true;other.Alias="다른 게임";
            var assetPath=Path.Combine(folder,"input","SharedAtlas");Directory.CreateDirectory(assetPath);File.WriteAllText(Path.Combine(assetPath,"guide.txt"),"guide");var asset=new Package{Id=Guid.NewGuid().ToString("N"),IsReal=true,IsContent=true,Registered=false,Source=assetPath,DetectedRoot=assetPath,SearchRoot=p.SearchRoot,Folder="SharedAtlas",Name="SharedAtlas"};p.RelatedFolders.Add(new(){Id=asset.Id,Source=asset.Source,Name=asset.Folder,Alias="공통 설정집"});other.RelatedFolders.Add(new(){Id=asset.Id,Source=asset.Source,Name=asset.Folder,Alias="공통 설정집"});var all=new List<Package>{p,other,asset};ContentLinks.Normalize(all);
            var scan=GameScanner.Scan(folder);LibraryStore.EnsureIdentity(p.Source,p.Id);LibraryStore.EnsureIdentity(other.Source,other.Id);scan=GameScanner.Scan(folder);var play=new PlayerDocument{Games=[new(){Id=p.Id,Executable="Game.exe",WorkingDirectory="Data",Arguments="--keep"},new(){Id=other.Id,Executable="Game.exe"}]};var tags=new TagCatalog();var plan=new WorkspaceDocument{SearchRoot=folder,SearchLocations=[new(){Path=folder}],Destination=Path.Combine(folder,"library"),BackupRoot=Path.Combine(folder,"backups"),Packages=all,Checkpoints=all.Select(p=>WorkspaceReconciler.Capture(p,scan)).ToList(),SelectedId=p.Id};return(plan,tags,play,p,other,asset);
        }

        (RenameBatch Batch,WorkspaceDocument Plan,TagCatalog Tags,PlayerDocument Play,Package A,Package B) BatchData(string folder)
        {var f=Data(folder);var data=Path.Combine(folder,"data");new WorkspaceStore(Path.Combine(data,"workspace.json")).Save(f.Plan);new TagCatalogStore(Path.Combine(data,"tags.json")).Save(f.Tags);new PlayerStore(f.Plan.Destination).Save(f.Play);return(new RenameBatch(data),f.Plan,f.Tags,f.Play,f.Main,f.Second);}
        RenameTarget Target(Package p,string name)=>new(){PackageId=p.Id,Original=p.Source,Current=p.Source,Name=name};
        Test("batch-independent-renames-preserve-launch-alias-and-identity",folder=>{var f=BatchData(folder);f.Batch.Begin(f.Plan,f.Tags,f.Play,[Target(f.A,"Garden"),Target(f.B,"Train")]);var r=f.Batch.ContinueAsync().GetAwaiter().GetResult();Check(r.Status=="Completed"&&!f.Batch.HasPending&&r.Items.All(t=>Directory.Exists(t.Current)),"Rename unfinished");var plan=new WorkspaceStore(Path.Combine(folder,"data","workspace.json")).Load().Document!;Check(plan.Packages.Single(p=>p.Id==f.A.Id).Alias==f.A.Alias&&r.Current.Play.Games.Single(g=>g.Id==f.A.Id).Executable=="Game.exe"&&LibraryStore.ReadIdentity(r.Items[0].Current)!.GameId==f.A.Id,"Identity or launch changed");Check(new BackupEngine(f.Plan.BackupRoot).Inventory().All(i=>!i.Job.RetainedForRecovery),"Retention not released");});
        Test("swap-names-is-one-recoverable-group",folder=>{var f=BatchData(folder);var a=f.A.Source;var b=Path.Combine(Path.GetDirectoryName(a)!,"Other");Directory.Move(f.B.Source,b);f.B.Source=f.B.DetectedRoot=b;f.B.SearchRoot=f.A.SearchRoot;f.B.Folder=f.B.Name="Other";f.Plan.Checkpoints=f.Plan.Packages.Select(p=>WorkspaceReconciler.Capture(p,GameScanner.Scan(folder))).ToList();var r=f.Batch.Begin(f.Plan,f.Tags,f.Play,[Target(f.A,"Other"),Target(f.B,"Bundle")]);Check(r.Groups.Count==1,"Swap not grouped");r=f.Batch.ContinueAsync().GetAwaiter().GetResult();Check(LibraryStore.ReadIdentity(a)!.GameId==f.B.Id&&LibraryStore.ReadIdentity(b)!.GameId==f.A.Id,"Swap misplaced identity");});
        Test("nested-parent-child-renames-update-relative-launch-and-links",folder=>{var f=BatchData(folder);var child=new Package{Id=Guid.NewGuid().ToString("N"),IsReal=true,Registered=true,Source=Path.Combine(f.A.Source,"OtherGame"),DetectedRoot=Path.Combine(f.A.Source,"OtherGame"),SearchRoot=f.A.SearchRoot,Folder="OtherGame",Name="OtherGame"};LibraryStore.EnsureIdentity(child.Source,child.Id);f.A.Contents.Add(new(){Id=child.Id,Path="OtherGame",Role="game"});f.A.OmittedFolders.Add("OtherGame");f.Plan.Packages.Add(child);f.Play.Games.Add(new(){Id=child.Id,Executable="Other.exe"});f.Plan.Checkpoints=f.Plan.Packages.Select(p=>WorkspaceReconciler.Capture(p,GameScanner.Scan(folder))).ToList();var r=f.Batch.Begin(f.Plan,f.Tags,f.Play,[Target(f.A,"ParentNew"),Target(child,"ChildNew")]);Check(r.Groups.Count==1,"Nested scopes split");r=f.Batch.ContinueAsync().GetAwaiter().GetResult();var main=r.Current.Plan.Packages.Single(p=>p.Id==f.A.Id);var sub=r.Current.Plan.Packages.Single(p=>p.Id==child.Id);Check(sub.Source==Path.Combine(main.Source,"ChildNew")&&Directory.Exists(sub.Source)&&main.OmittedFolders.Contains("ChildNew"),"Nested references lost");});
        Test("batch-case-only-name-change",folder=>{var f=BatchData(folder);f.Batch.Begin(f.Plan,f.Tags,f.Play,[Target(f.A,"bundle")]);var r=f.Batch.ContinueAsync().GetAwaiter().GetResult();Check(FolderRename.Exact(r.Items[0].Current)&&Path.GetFileName(r.Items[0].Current)=="bundle","Case not applied");});
        Test("duplicate-target-and-existing-folder-refuse-before-backup",folder=>{var f=BatchData(folder);Directory.CreateDirectory(Path.Combine(Path.GetDirectoryName(f.A.Source)!,"Occupied"));Refuse(()=>f.Batch.Begin(f.Plan,f.Tags,f.Play,[Target(f.A,"Occupied")]));Check(!f.Batch.HasPending&&!Directory.Exists(f.Plan.BackupRoot),"Preflight changed files");var same=Target(f.A,"Next");Refuse(()=>f.Batch.Begin(f.Plan,f.Tags,f.Play,[same,Target(f.A,"Another")]));});
        Test("all-backups-finish-before-first-physical-step",folder=>{var f=BatchData(folder);f.Batch.Checkpoint=p=>{if(p=="step-intent"){Check(new BackupEngine(f.Plan.BackupRoot).ListJobs(false).Count(j=>j.Status=="Completed")==2,"Rename before all backups");throw new IOException("stop");}};f.Batch.Begin(f.Plan,f.Tags,f.Play,[Target(f.A,"A"),Target(f.B,"B")]);Refuse(()=>f.Batch.ContinueAsync().GetAwaiter().GetResult());Check(Directory.Exists(f.A.Source)&&Directory.Exists(f.B.Source),"Moved before intent");Check(new BackupEngine(f.Plan.BackupRoot).Inventory().All(i=>!i.Selectable),"Pending backup deletable");});
        Test("stop-keeps-completed-group-and-restores-unfinished-group",folder=>{var f=BatchData(folder);int groups=0;f.Batch.Checkpoint=p=>{if(p=="group-completed"&&++groups==1)throw new IOException("stop after first");};f.Batch.Begin(f.Plan,f.Tags,f.Play,[Target(f.A,"A"),Target(f.B,"B")]);Refuse(()=>f.Batch.ContinueAsync().GetAwaiter().GetResult());f.Batch.Checkpoint=null;var r=f.Batch.StopAsync(false).GetAwaiter().GetResult();Check(r.Status=="Stopped"&&Path.GetFileName(r.Items[0].Current)=="A"&&r.Items[1].Current==f.B.Source&&!f.Batch.HasPending,"Keep-completed policy failed");});
        Test("stop-undo-restores-completed-groups",folder=>{var f=BatchData(folder);f.Batch.Checkpoint=p=>{if(p=="group-completed")throw new IOException("stop");};f.Batch.Begin(f.Plan,f.Tags,f.Play,[Target(f.A,"A"),Target(f.B,"B")]);Refuse(()=>f.Batch.ContinueAsync().GetAwaiter().GetResult());f.Batch.Checkpoint=null;var r=f.Batch.StopAsync(true).GetAwaiter().GetResult();Check(r.Items.All(t=>t.Current==t.Original&&Directory.Exists(t.Original))&&r.Status=="RolledBack","Undo-all failed");});
        Test("partial-swap-stop-restores-whole-dependent-group",folder=>{var f=BatchData(folder);var b=Path.Combine(Path.GetDirectoryName(f.A.Source)!,"Other");Directory.Move(f.B.Source,b);f.B.Source=f.B.DetectedRoot=b;f.B.SearchRoot=f.A.SearchRoot;f.B.Folder=f.B.Name="Other";f.Plan.Checkpoints=f.Plan.Packages.Select(p=>WorkspaceReconciler.Capture(p,GameScanner.Scan(folder))).ToList();int steps=0;f.Batch.Checkpoint=p=>{if(p=="step-recorded"&&++steps==3)throw new IOException("stop during swap finish");};f.Batch.Begin(f.Plan,f.Tags,f.Play,[Target(f.A,"Other"),Target(f.B,"Bundle")]);Refuse(()=>f.Batch.ContinueAsync().GetAwaiter().GetResult());f.Batch.Checkpoint=null;var r=f.Batch.StopAsync(false).GetAwaiter().GetResult();Check(r.Items.All(t=>t.Current==t.Original)&&LibraryStore.ReadIdentity(f.A.Source)!.GameId==f.A.Id,"Half swap kept");});
        foreach(var point in new[]{"backup-recorded","step-intent","step-captured","step-moved","step-metadata","step-recorded","group-completed"})Test("process-kill-batch-recovery-"+point,folder=>{var f=BatchData(folder);f.Batch.Begin(f.Plan,f.Tags,f.Play,[Target(f.A,"CrashA"),Target(f.B,"CrashB")]);var start=new ProcessStartInfo(Environment.ProcessPath!){UseShellExecute=false,RedirectStandardOutput=true,CreateNoWindow=true};foreach(var a in new[]{"--batch-child",Path.Combine(folder,"data"),point})start.ArgumentList.Add(a);using var child=Process.Start(start)!;var line=child.StandardOutput.ReadLineAsync();if(!line.Wait(TimeSpan.FromSeconds(30))||line.Result!="READY"){if(!child.HasExited)child.Kill(true);throw new Exception("Child did not reach checkpoint");}child.Kill(true);child.WaitForExit();var r=f.Batch.ContinueAsync().GetAwaiter().GetResult();Check(r.Status=="Completed"&&r.Items.All(t=>Directory.Exists(t.Current))&&!f.Batch.HasPending,"Batch recovery failed");});
        Test("recommendations-are-small-and-exclude-internal-assets",folder=>{var f=Data(folder);File.WriteAllText(Path.Combine(f.Main.Source,"readme.txt"),"read");File.WriteAllText(Path.Combine(f.Main.Source,"Data","cover.png"),"fixture");var files=PreviewFiles.Candidates(f.Main,GameScanner.Scan(folder));var rec=PreviewFiles.Recommended(f.Main,files);Check(rec.Count<=6&&rec.Any(x=>Path.GetFileName(x.Path)=="readme.txt")&&!rec.Any(x=>x.Path.Contains("Data\\cover")),"Bad recommendation");Check(files.Any(x=>x.Path.Contains("Data\\cover")),"Full list lost asset");});
        Test("preview-launch-does-not-mutate-default-arguments-or-history",folder=>{var f=Data(folder);var stored=f.Play.Games.Single(g=>g.Id==f.Main.Id);var before=JsonSerializer.Serialize(stored);var info=PreviewLaunch.StartInfo(f.Main,stored,"OtherGame/Other.exe",true);Check(info.Arguments==""&&info.WorkingDirectory.EndsWith("OtherGame")&&JsonSerializer.Serialize(stored)==before,"Preview changed settings");var normal=PreviewLaunch.StartInfo(f.Main,stored,"Game.exe",true);Check(normal.Arguments==stored.Arguments&&normal.WorkingDirectory.EndsWith("Data"),"Configured launch settings lost");});
        Test("preview-launch-refuses-independent-game-scope",folder=>{var f=Data(folder);f.Main.OmittedFolders.Add("OtherGame");Refuse(()=>PreviewLaunch.StartInfo(f.Main,null,"OtherGame/Other.exe"));});
        Test("batch-rejects-empty-backup-root",folder=>{var f=BatchData(folder);f.Plan.BackupRoot="";Refuse(()=>f.Batch.Begin(f.Plan,f.Tags,f.Play,[Target(f.A,"A")]));Check(!f.Batch.HasPending,"Empty backup root accepted");});
        Test("changed-source-after-backup-stops-before-rename",folder=>{var f=BatchData(folder);f.Batch.Checkpoint=p=>{if(p=="backup-recorded")File.AppendAllText(Path.Combine(f.A.Source,"Game.exe"),"changed after backup");};f.Batch.Begin(f.Plan,f.Tags,f.Play,[Target(f.A,"A")]);Refuse(()=>f.Batch.ContinueAsync().GetAwaiter().GetResult());Check(Directory.Exists(f.A.Source)&&!Directory.Exists(Path.Combine(Path.GetDirectoryName(f.A.Source)!,"A")),"Changed source moved");f.Batch.Checkpoint=null;f.Batch.StopAsync(false).GetAwaiter().GetResult();});
        Test("locked-library-metadata-retains-journal-and-can-recover",folder=>{var f=BatchData(folder);new LibraryStore(f.Plan.Destination).Register(f.A,[],GameScanner.Scan(folder));var csv=Path.Combine(f.Plan.Destination,"indierun-library.csv");f.Batch.Begin(f.Plan,f.Tags,f.Play,[Target(f.A,"A")]);using(var locked=new FileStream(csv,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){Refuse(()=>f.Batch.ContinueAsync().GetAwaiter().GetResult());Check(f.Batch.HasPending&&new BackupEngine(f.Plan.BackupRoot).Inventory().All(i=>!i.Selectable),"Lost pending or retention");}var r=f.Batch.ContinueAsync().GetAwaiter().GetResult();Check(r.Status=="Completed"&&Directory.Exists(r.Items[0].Current),"Metadata recovery failed");});
        Test("unmatched-files-do-not-become-recommendations",folder=>{var f=Data(folder);File.WriteAllText(Path.Combine(f.Main.Source,"settings.ini"),"setting");f.Main.Contents.Clear();f.Main.RelatedFolders.Clear();var files=PreviewFiles.Candidates(f.Main,GameScanner.Scan(folder));Check(files.Count>0&&PreviewFiles.Recommended(f.Main,files).Count==0,"Forced irrelevant recommendation");});
        Test("demo-relocation-rebases-rename-history",folder=>{var kit=Path.Combine(folder,"kit");var appdir=Path.Combine(kit,"IndieRun");var mock=Path.Combine(kit,"MockData");var game=Path.Combine(mock,"Games","Demo");Directory.CreateDirectory(game);File.WriteAllText(Path.Combine(game,"Game.exe"),"fixture, do not execute");File.WriteAllText(Path.Combine(mock,"demo-manifest.json"),JsonSerializer.Serialize(new DemoManifest{Games=[new(){Key="Demo",Folder="Games/Demo",Executable="Game.exe"}]}));DemoSetup.Initialize(appdir);var data=Path.Combine(appdir,"data");var plan=new WorkspaceStore(Path.Combine(data,"workspace.json")).Load().Document!;var batch=new RenameBatch(data);batch.Begin(plan,new TagCatalogStore(Path.Combine(data,"tags.json")).Load(),new PlayerStore(plan.Destination).Load(),[Target(plan.Packages.Single(),"RenamedDemo")]);batch.ContinueAsync().GetAwaiter().GetResult();var relocated=Path.Combine(folder,"relocated-kit");Directory.Move(kit,relocated);DemoSetup.Initialize(Path.Combine(relocated,"IndieRun"));var last=new RenameBatch(Path.Combine(relocated,"IndieRun","data")).LoadLast()!;Check(last.Items.All(t=>GameScanner.Within(t.Current,relocated)&&GameScanner.Within(t.Original,relocated))&&Directory.Exists(last.Items.Single().Current),"History paths not relocated");});
        SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());
        foreach(var size in new[]{(820d,560d),(1000d,700d)})Test("rename-editor-and-results-layout-"+size.Item1,folder=>{var f=BatchData(folder);var w=Window(folder,f.Plan.Packages,GameScanner.Scan(folder));Window? editor=null,result=null;try{new System.Windows.Interop.WindowInteropHelper(w).EnsureHandle();editor=(Window)Call(w,"BuildRenameEditor",new List<RenameTarget>{Target(f.A,"Bundle"),Target(f.B,"Bundle")},null)!;var r=f.Batch.Begin(f.Plan,f.Tags,f.Play,[Target(f.A,"A"),Target(f.B,"B")]);result=(Window)Call(w,"BuildRenameProgress",r,false)!;foreach(var dialog in new[]{editor,result}){var body=(FrameworkElement)dialog.Content;body.Measure(new Size(size.Item1,size.Item2));body.Arrange(new Rect(0,0,size.Item1,size.Item2));body.UpdateLayout();Check(Visual(body).OfType<Button>().Where(b=>b.IsVisible).All(b=>b.ActualWidth<2||b.TranslatePoint(new Point(),body).X+b.ActualWidth<=body.ActualWidth+1),"Button clipped");}}finally{editor?.Close();result?.Close();Close(w);}});
        File.WriteAllText(args[1],JsonSerializer.Serialize(new{root,total=results.Count,passed=results.Count-failed,failed,results},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"RESULT {results.Count-failed}/{results.Count}");return failed==0?0:1;
    }
}






